(()=>{
 const CLIPS={"emerge": "data:audio/wav;base64,", "hit": "data:audio/wav;base64,", "semenych0": "data:audio/wav;base64,", "semenych1": "data:audio/wav;base64,", "semenych2": "data:audio/wav;base64,", "glebas": "data:audio/wav;base64,", "mirosh": "data:audio/wav;base64,", "domik": "data:audio/wav;base64,", "egor": "data:audio/wav;base64,", "drew0": "data:audio/wav;base64,", "edik0": "data:audio/wav;base64,", "edik1": "data:audio/wav;base64,", "edik2": "data:audio/wav;base64,", "bodya0": "data:audio/wav;base64,", "bodya1": "data:audio/wav;base64,", "tema0": "data:audio/wav;base64,", "tema1": "data:audio/wav;base64,", "yarik": "data:audio/wav;base64,", "iiist0": "data:audio/wav;base64,", "iiist2": "data:audio/wav;base64,", "kostyan0": "data:audio/wav;base64,", "kostyan1": "data:audio/wav;base64,", "kostyan2": "data:audio/wav;base64,", "explosion": "data:audio/wav;base64,", "mashkovHit": "data:audio/wav;base64,", "dariy0": "data:audio/wav;base64,", "dariy1": "data:audio/wav;base64,", "kstruve": "data:audio/wav;base64,"};
 let muted=false,lastPop=-Infinity,context=null,master=null,loading=null,decodeQueue=null;
 const buffers=new Map(),active=new Set(),recent=new Map();
 let musicElement=null,musicSource=null,musicGain=null,musicMuted=false;
 const connectMusic=()=>{
  if(!context||!musicElement||musicSource)return;
  musicSource=context.createMediaElementSource(musicElement);musicGain=context.createGain();
  musicGain.gain.value=musicMuted?0:.405;
  musicSource.connect(musicGain);musicGain.connect(context.destination);
 };
 const MAX_VOICES=8;
 const diagnostics=new URLSearchParams(location.search).has('diag');
 const metrics=()=>{if(diagnostics)window.dispatchEvent(new CustomEvent('bandwhack-audio-metrics',{detail:{state:context?.state||'off',active:active.size}}));};
 const stopVoice=voice=>{try{voice.source.stop();}catch(error){}voice.source.disconnect();voice.gain.disconnect();active.delete(voice);metrics();};
 const stopAll=()=>{for(const voice of [...active])stopVoice(voice);recent.clear();};
 const ensureContext=()=>{
  if(context)return context;
  const AudioEngine=window.AudioContext||window.webkitAudioContext;if(!AudioEngine)return null;
  try{if(typeof navigator!=='undefined'&&navigator.audioSession)navigator.audioSession.type='playback';}catch(error){}
  context=new AudioEngine({latencyHint:'interactive'});master=context.createGain();master.gain.value=muted?0:1;master.connect(context.destination);connectMusic();
  // Data is decoded in a small sequential queue, never by starting media players.
  decodeQueue=Object.entries(CLIPS).sort(([a],[b])=>Number(!['hit','emerge','explosion'].includes(a))-Number(!['hit','emerge','explosion'].includes(b)));
  loading=(async()=>{
   for(const [name,url] of decodeQueue){
    const binary=atob(url.slice(url.indexOf(',')+1)),bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
    try{buffers.set(name,await new Promise((resolve,reject)=>context.decodeAudioData(bytes.buffer,resolve,reject)));}catch(error){}
   }
  })();
  return context;
 };
 const unlock=()=>{
  const ctx=ensureContext();if(!ctx)return;
  if(ctx.state!=='running')ctx.resume().catch(()=>{});
  // A one-sample silent buffer unlocks the context within the real gesture; no character clip is played.
  if(!ctx._bandwhackUnlocked){
   const silent=ctx.createBufferSource();silent.buffer=ctx.createBuffer(1,1,ctx.sampleRate);silent.connect(ctx.destination);silent.onended=()=>silent.disconnect();silent.start();ctx._bandwhackUnlocked=true;metrics();
  }
 };
 const playReady=(name,requested)=>{
  if(muted||document.hidden||performance.now()-requested>160||!context||context.state!=='running')return;
  const buffer=buffers.get(name);if(!buffer)return;
  const now=performance.now(),previous=recent.get(name)||-Infinity;
  if((name==='hit'||name==='emerge')&&now-previous<55)return;
  recent.set(name,now);
  if(active.size>=MAX_VOICES)stopVoice(active.values().next().value);
  const source=context.createBufferSource(),gain=context.createGain();source.buffer=buffer;
  gain.gain.value=name==='emerge'?.7:1;source.connect(gain);gain.connect(master);
  const voice={source,gain};active.add(voice);source.onended=()=>{source.disconnect();gain.disconnect();active.delete(voice);metrics();};source.start();metrics();
 };
 const playClip=(name,requested=performance.now())=>{
  if(muted||document.hidden)return;
  if(buffers.has(name))playReady(name,requested);
  // Drop unready/old effects rather than accumulating a burst for the next touch.
 };
 for(const event of ['pointerdown','touchend','keydown'])document.addEventListener(event,unlock,{capture:true,passive:true});
 window.addEventListener('bandwhack-play',unlock);
 // Separate music and effects gains share one context; muting music never changes the media session.
 window.BandWhackAudio={
  attachMusic(element){musicElement=element;musicElement.volume=1;connectMusic();},
  setMusicMuted(value){musicMuted=!!value;if(musicGain)musicGain.gain.value=musicMuted?0:.405;},
  playMusic(){unlock();connectMusic();if(musicElement)musicElement.play().catch(()=>{});},
  pauseMusic(){musicElement?.pause();}
 };
 window.addEventListener('bandwhack-mute',event=>{muted=event.detail.muted;if(master)master.gain.value=muted?0:1;if(muted)stopAll();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAll();});
 window.addEventListener('pagehide',stopAll);
 window.addEventListener('bandwhack-emerge',()=>{const now=performance.now();if(muted||now-lastPop<90)return;lastPop=now;playClip('emerge');});
 document.addEventListener('bandwhack-mashkov-hit',()=>playClip('mashkovHit'));
 document.addEventListener('bandwhack-explosion',()=>playClip('explosion'));

 document.addEventListener('bandwhack-hit',event=>{
  if(muted)return;
  playClip('hit');
  if(event.detail?.character==='Semenych')playClip('semenych'+Math.floor(Math.random()*3));
  if(event.detail?.character==='Mirosh')playClip('mirosh');
  if(event.detail?.character==='Bodya')playClip(Math.random()<.25?'bodya0':'bodya1');
  if(event.detail?.character==='Struve')playClip('kstruve');
  if(event.detail?.character==='Dariy')playClip('dariy'+Math.floor(Math.random()*2));
  if(event.detail?.character==='Tema')playClip('tema'+Math.floor(Math.random()*2));
  if(event.detail?.character==='Yarik')playClip('yarik');
  if(event.detail?.character==='Kostyan'){const pick=Math.random();playClip(pick<.5?'kostyan0':pick<.75?'kostyan1':'kostyan2');}
  if(event.detail?.character==='iiist')playClip(Math.random()<.5?'iiist0':'iiist2');
  if(event.detail?.character==='Egor')playClip('egor');
  if(event.detail?.character==='Drew')playClip('drew0');
  if(event.detail?.character==='Edik')playClip('edik'+Math.floor(Math.random()*3));
  if(event.detail?.character==='Domik')playClip('domik');
  if(event.detail?.character==='Glebas')playClip('glebas');
 });
})();
